const app=document.querySelector('#app');
const API=window.NINHO_API_BASE||'/api';
const REMOTE_API=API.startsWith('https://')||API.startsWith('/ninho-api/');
const PUBLIC_API_KEY=window.NINHO_SUPABASE_KEY||'';
const INVITE_BASE=`${location.origin}/convite/`;
const publicInviteUrl=token=>`${INVITE_BASE}${encodeURIComponent(token)}`;
let data={event:{baby:'Anya'},guests:[],checklist:[],gifts:[],messages:[],guesses:[],giftsOpen:false};
let page='home',priority='all',guestQuery='',guestFilter='all',checkQuery='';
let previewMode=false,demoDb,adminMode=false;
const $=(s,root=document)=>root.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function api(path,opts={},retried=false){const headers={'Content-Type':'application/json',...(REMOTE_API?{apikey:PUBLIC_API_KEY}:{}),...(sessionStorage.getItem('ninho-admin-token')?{Authorization:`Bearer ${sessionStorage.getItem('ninho-admin-token')}`}:{ } ),...(opts.headers||{})};try{const r=await fetch(API+path,{...opts,headers});const j=await r.json().catch(()=>({}));if(r.ok)return j;if(r.status===401&&REMOTE_API&&!retried&&!path.startsWith('/invite/')&&!path.startsWith('/rsvp/')&&!path.startsWith('/public-')&&!path.startsWith('/admin/login')){await authenticateAdmin();return api(path,opts,true)}if(r.status!==404||REMOTE_API)throw Error(j.error||'Não foi possível concluir.')}catch(e){if(REMOTE_API)throw e;if(e.message&&e.message!=='Failed to fetch'&&!e.message.includes('fetch'))throw e}previewMode=true;return demoApi('/api'+path,opts)}
async function authenticateAdmin(){const password=prompt('Área da família: digite a senha administrativa do Lá vem cegonha.');if(!password)throw Error('Acesso cancelado.');const r=await fetch(API+'/admin/login',{method:'POST',headers:{'Content-Type':'application/json',apikey:PUBLIC_API_KEY},body:JSON.stringify({password})});const j=await r.json().catch(()=>({}));if(!r.ok)throw Error(j.error||'Não foi possível entrar.');sessionStorage.setItem('ninho-admin-token',j.token)}
async function getDemoDb(){if(demoDb)return demoDb;try{demoDb=JSON.parse(localStorage.getItem('ninho-vercel-preview-v1')||'null')}catch{}if(!demoDb){try{const r=await fetch('/seed.json');demoDb=await r.json()}catch{demoDb={event:{baby:'Anya',message:'Venha celebrar conosco!'},guests:[],checklist:[]}};localStorage.setItem('ninho-vercel-preview-v1',JSON.stringify(demoDb))}return demoDb}
async function demoApi(path,opts={}){const db=await getDemoDb(),parts=path.split('/').filter(Boolean).map(decodeURIComponent),method=opts.method||'GET',b=opts.body?JSON.parse(opts.body):{};if(parts[0]!=='api')throw Error('Recurso não encontrado');if(parts[1]==='data')return {...db,gifts:db.gifts||[],messages:db.messages||[],giftsOpen:new Intl.DateTimeFormat('sv-SE',{timeZone:'America/Sao_Paulo',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date())>(db.event.date||'2026-11-29')};if(parts[1]==='public-messages'&&method==='GET')return {messages:(db.messages||[]).filter(m=>m.approved)};if(parts[1]==='public-messages'&&method==='POST'){(db.messages??=[]).unshift({id:crypto.randomUUID(),author_name:b.name,message:b.message,approved:false,created_at:new Date().toISOString()});localStorage.setItem('ninho-vercel-preview-v1',JSON.stringify(db));return {ok:true}}if(parts[1]==='messages'&&method==='PATCH'){const m=(db.messages||[]).find(m=>m.id===parts[2]);if(!m)throw Error('Recado não encontrado');m.approved=!!b.approved;localStorage.setItem('ninho-vercel-preview-v1',JSON.stringify(db));return {message:m}}if(parts[1]==='messages'&&method==='DELETE'){db.messages=(db.messages||[]).filter(m=>m.id!==parts[2]);localStorage.setItem('ninho-vercel-preview-v1',JSON.stringify(db));return {ok:true}}if(parts[1]==='event'&&method==='PUT'){db.event={...db.event,...b};localStorage.setItem('ninho-vercel-preview-v1',JSON.stringify(db));return {event:db.event}}if(parts[1]==='guests'&&parts.length===2&&method==='POST'){const guest={id:crypto.randomUUID?.()||String(Date.now()),token:Math.random().toString(36).slice(2,14),name:b.name,phone:b.phone,note:b.note,status:'pending',partySize:1};db.guests.push(guest);localStorage.setItem('ninho-vercel-preview-v1',JSON.stringify(db));return {guest}}if(parts[1]==='guests'&&method==='PATCH'){const guest=db.guests.find(g=>g.id===parts[2]);if(!guest)throw Error('Convidado não encontrado');Object.assign(guest,b);localStorage.setItem('ninho-vercel-preview-v1',JSON.stringify(db));return {guest}}if(parts[1]==='invite'&&method==='GET'){const guest=db.guests.find(g=>g.token===parts[2]);if(!guest)throw Error('Convite não encontrado');return {guest,event:db.event}}if(parts[1]==='rsvp'&&method==='POST'){const guest=db.guests.find(g=>g.token===parts[2]);if(!guest)throw Error('Convite não encontrado');guest.status=b.status;guest.partySize=b.status==='yes'?Number(b.partySize||1):1;localStorage.setItem('ninho-vercel-preview-v1',JSON.stringify(db));return {guest}}if(parts[1]==='gifts'&&['POST','PATCH','DELETE'].includes(method)&&new Intl.DateTimeFormat('sv-SE',{timeZone:'America/Sao_Paulo',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date())<=(db.event.date||'2026-11-29'))throw Error('O registro de presentes abre no dia seguinte ao chá.');if(parts[1]==='gifts'&&method==='POST'){const gift={id:crypto.randomUUID(),guest_id:b.guestId||null,donor_name:b.donorName,item_id:b.itemId||null,gift_description:b.description,message:b.message||'',publish_message:!!b.publishMessage,created_at:new Date().toISOString()};(db.gifts??=[]).unshift(gift);const item=db.checklist.find(x=>x.id===b.itemId);if(item)item.status='have';localStorage.setItem('ninho-vercel-preview-v1',JSON.stringify(db));return {gift}}if(parts[1]==='gifts'&&method==='PATCH'){const gift=(db.gifts||[]).find(x=>x.id===parts[2]);if(!gift)throw Error('Presente não encontrado');gift.message=b.message;gift.publish_message=!!b.publishMessage;localStorage.setItem('ninho-vercel-preview-v1',JSON.stringify(db));return {gift}}if(parts[1]==='gifts'&&method==='DELETE'){db.gifts=(db.gifts||[]).filter(x=>x.id!==parts[2]);localStorage.setItem('ninho-vercel-preview-v1',JSON.stringify(db));return {ok:true}}if(parts[1]==='checklist'&&method==='PATCH'){const item=db.checklist.find(x=>x.id===parts[2]);if(!item)throw Error('Item não encontrado');item.status=b.status;localStorage.setItem('ninho-vercel-preview-v1',JSON.stringify(db));return {item}}throw Error('Recurso não encontrado')}
function toast(text){const t=$('#toast');t.textContent=text;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2500)}
function dateText(date,time){if(!date)return 'Data a definir';const d=new Date(date+'T12:00:00');return d.toLocaleDateString('pt-BR',{weekday:'long',day:'2-digit',month:'long'})+(time?' · '+time:'')}
function invitePoster(){return `<figure class="invite-art"><img class="invite-poster" src="/assets/convite-anya-final.jpg" alt="Convite final do chá de bebê da Anya: 29 de novembro às 13h, Praia da Brisa, Guaratiba"></figure>`}
function shopUrl(item){
 const diapers={'Fralda P':'https://www.drogariaspacheco.com.br/fraldas/pampers/P?PS=9','Fralda RN':'https://www.drogariaspacheco.com.br/fraldas/pampers/rn','Fralda M':'https://www.drogariaspacheco.com.br/fraldas/pampers/m'};
 if(item.category==='Fraldas'&&diapers[item.name])return diapers[item.name];
 const query=`${item.name} bebê`.normalize('NFC').replace(/[\/–]/g,' ').replace(/\s+/g,' ').trim();
 return `https://www.magazineluiza.com.br/busca/${encodeURIComponent(query.replaceAll(' ','+'))}/`;
}
const priceBands={'':'Sem faixa definida',ate50:'Até R$ 50','50a100':'R$ 50 a R$ 100','100a200':'R$ 100 a R$ 200',acima200:'Acima de R$ 200'};
function storeLinks(item){return Array.isArray(item.shop_links)&&item.shop_links.length?item.shop_links:[{label:'Buscar em lojas',url:shopUrl(item)}]}
function giftCatalog(items,token=''){
 const group=Object.entries(priceBands).map(([key,title])=>({key,title,items:items.filter(x=>(x.price_band||'')===key)})).filter(x=>x.items.length);
 return `<section id="gift-catalog" class="rsvp-panel gift-catalog" tabindex="-1"><h2>Lista do enxoval da Anya</h2><p>Escolha a faixa de valor e compare lojas. Faixas informadas pela família são estimativas; confira o preço e a entrega no site da loja.</p>${group.length?'':'<p class="empty-state">Todos os itens da lista já foram separados. Obrigado pelo carinho!</p>'}${group.map(g=>`<details><summary>${esc(g.title)} <span>${g.items.length} itens</span></summary><div class="gift-catalog-items">${g.items.map(item=>`<div class="gift-choice"><strong>${esc(item.name)}</strong><small>${esc(item.quantity||'')}</small><div class="gift-choice-actions">${storeLinks(item).map(link=>`<a href="${esc(link.url)}" target="_blank" rel="noopener noreferrer">${esc(link.label)} ↗</a>`).join('')}${token?`<button type="button" data-reserve="${esc(item.id)}">Vou levar este item</button>`:''}</div></div>`).join('')}</div></details>`).join('')}</section>`
}
async function publicChecklist(){if(!REMOTE_API){const db=await getDemoDb();return db.checklist.filter(item=>item.status!=='have'&&item.status!=='expected')}const res=await fetch(API+'/public-checklist',{headers:{apikey:PUBLIC_API_KEY},cache:'no-store'});if(!res.ok)throw Error('Lista indisponível');const body=await res.json();return body.checklist}
async function showGiftCatalog(){try{const items=await publicChecklist();$('#gift-catalog')?.remove();const wrap=$('.public-wrap');wrap.insertAdjacentHTML('beforeend',giftCatalog(items,location.pathname.startsWith('/convite/')?decodeURIComponent(location.pathname.split('/')[2]||''):''));const catalog=$('#gift-catalog');catalog.scrollIntoView({behavior:'smooth',block:'start'});catalog.focus({preventScroll:true});catalog.querySelectorAll('[data-reserve]').forEach(button=>button.onclick=async()=>{button.disabled=true;try{await api('/reserve/'+encodeURIComponent(button.dataset.reserve),{method:'POST',body:JSON.stringify({token:decodeURIComponent(location.pathname.split('/')[2]||'')})});toast('Item reservado para você. Avise quando comprar.');await showGiftCatalog();}catch(err){toast(err.message);button.disabled=false}})}catch{toast('Não foi possível abrir a lista agora.')}}
async function loadMural(){
 try{
  let messages=[];
  if(REMOTE_API){const response=await fetch(API+'/mural',{headers:{apikey:PUBLIC_API_KEY},cache:'no-store'});if(!response.ok)return;messages=(await response.json()).messages||[]}
  else messages=(await getDemoDb()).gifts?.filter(g=>g.publish_message&&g.message).map(g=>({donor_name:g.donor_name,message:g.message}))||[];
  if(!messages.length)return;
  $('.public-wrap')?.insertAdjacentHTML('beforeend',`<section class="rsvp-panel gift-mural"><h2>Recadinhos para a Anya ♡</h2>${messages.map(g=>`<blockquote><p>${esc(g.message)}</p><footer>— ${esc(g.donor_name)}</footer></blockquote>`).join('')}</section>`);
 }catch{}
}
function contributionPanel(event){if(!event.pixKey||!event.pixRecipient)return '';return `<section class="rsvp-panel contribution-panel"><h2>Contribuição voluntária</h2><p>Se preferir ajudar com um valor em vez de um presente físico, use a chave PIX abaixo. O site não confirma pagamentos.</p><p><strong>${esc(event.pixRecipient)}</strong></p><p class="pix-key">${esc(event.pixKey)}</p><button type="button" class="button button-primary" data-copy-pix="${esc(event.pixKey)}">Copiar chave PIX</button></section>`}
function bindPix(){document.querySelectorAll('[data-copy-pix]').forEach(button=>button.onclick=async()=>{try{await navigator.clipboard.writeText(button.dataset.copyPix);toast('Chave PIX copiada')}catch{prompt('Copie a chave PIX:',button.dataset.copyPix)}})}
function routePanel(event){if(!event.address)return '';const q=encodeURIComponent(event.address+' Rio de Janeiro RJ');return `<section class="rsvp-panel route-panel"><h2>Como chegar</h2><p>${esc(event.address)}</p><div class="gift-choice-actions"><a href="https://www.google.com/maps/search/?api=1&query=${q}" target="_blank" rel="noopener noreferrer">Abrir no Google Maps ↗</a><a href="https://waze.com/ul?q=${q}&navigate=yes" target="_blank" rel="noopener noreferrer">Abrir no Waze ↗</a></div></section>`}
async function loadWeather(event){const target=$('#weather-panel');if(!target||!event.date)return;const days=Math.floor((new Date(event.date+'T12:00:00')-new Date())/86400000);if(days<0||days>15){target.remove();return}try{let lat=event.weatherLat,lon=event.weatherLon;if(lat===''||lon===''){const geo=await fetch('https://geocoding-api.open-meteo.com/v1/search?name=Guaratiba&count=5&countryCode=BR&language=pt');const places=(await geo.json()).results||[];const place=places.find(p=>p.admin1==='Rio de Janeiro'&&p.admin2==='Rio de Janeiro');if(!place)throw Error();lat=place.latitude;lon=place.longitude}const url=`https://api.open-meteo.com/v1/forecast?latitude=${lat}&longitude=${lon}&daily=temperature_2m_max,precipitation_probability_max&timezone=America%2FSao_Paulo&forecast_days=16`;const response=await fetch(url);if(!response.ok)throw Error();const daily=(await response.json()).daily,index=daily.time.indexOf(event.date);if(index<0)throw Error();target.innerHTML=`<h2>Previsão para o dia do chá</h2><p>Região de Guaratiba · máxima de ${Math.round(daily.temperature_2m_max[index])} °C · chance máxima de chuva ${daily.precipitation_probability_max[index]??'—'}%.</p><small>Previsão sujeita a mudanças. Fonte: Open-Meteo.</small>`}catch{target.remove()}}
function weatherPanel(event){return event.date?'<section class="rsvp-panel" id="weather-panel" aria-live="polite">Consultando previsão…</section>':''}
function guessPanel(token,guess){if(!token)return '';return `<section class="rsvp-panel"><h2>Palpite para a Anya ♡</h2><p>Quando você acha que ela nasce? Quanto vai pesar? Só a família vê os palpites.</p><form id="guess-form" class="gift-form"><label>Data provável<input name="birthDate" type="date" value="${esc(guess?.birth_date||'')}"></label><label>Peso em gramas<input name="weightGrams" type="number" min="500" max="7000" required value="${esc(guess?.weight_grams||'')}"></label><button class="button button-primary">Salvar palpite</button><p class="message-feedback" role="status"></p></form></section>`}
function bindGuess(token){const form=$('#guess-form');if(!form)return;form.onsubmit=async e=>{e.preventDefault();const button=form.querySelector('button');button.disabled=true;try{await api('/guess/'+token,{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(form)))});form.querySelector('.message-feedback').textContent='Palpite salvo!'}catch(err){form.querySelector('.message-feedback').textContent=err.message}finally{button.disabled=false}}}
function messagePanel(token='',name=''){
 return `<section id="recados" class="rsvp-panel message-panel"><span class="eyebrow">UM CARINHO PARA A ANYA</span><h2>Deixe um recado ♡</h2><p>Desejos, dicas ou uma mensagem para guardar. Os recados aparecem aqui depois que a família aprovar.</p><form class="message-form"><label>Seu nome<input name="name" autocomplete="name" required minlength="2" maxlength="90" value="${esc(name)}" ${token?'readonly':''} placeholder="Como podemos chamar você?"></label><label>Seu recado<textarea name="message" required minlength="3" maxlength="500" rows="4" placeholder="Escreva sua mensagem para a Anya…"></textarea></label><button class="button button-primary" type="submit">Enviar recado ♡</button><p class="message-feedback" role="status" aria-live="polite"></p></form><div class="public-messages" aria-live="polite"></div></section>`;
}
async function loadPublicMessages(){
 const target=$('.public-messages');if(!target)return;
 try{const {messages}=await api('/public-messages',{headers:{Authorization:''}});if(!target.isConnected)return;target.innerHTML=messages.length?`<h3>Recados da família e dos amigos</h3>${messages.map(m=>`<blockquote><p>${esc(m.message)}</p><footer>— ${esc(m.author_name)}</footer></blockquote>`).join('')}`:''}catch{target.innerHTML=''}
}
function bindMessagePanel(token=''){
 const form=$('.message-form');if(!form)return;
 form.addEventListener('submit',async e=>{
  e.preventDefault();const button=form.querySelector('button'),feedback=form.querySelector('.message-feedback');button.disabled=true;feedback.textContent='Enviando…';
  try{await api('/public-messages',{method:'POST',headers:{Authorization:''},body:JSON.stringify({name:form.elements.name.value,message:form.elements.message.value,token})});form.elements.message.value='';feedback.textContent='Recado enviado! Ele aparecerá depois da aprovação da família.'}
  catch(err){feedback.textContent=err.message;button.disabled=false;return}button.disabled=false;
 });
 loadPublicMessages();
}
function inviteArt(){return invitePoster(data.event)}
function shell(content){document.body.classList.remove('boy');document.title='Lá vem cegonha · Anya';document.querySelector('meta[name="theme-color"]')?.setAttribute('content','#f5eafa');app.innerHTML=`<div class="app-shell"><header class="topbar"><a class="brand" href="#" data-page="home" aria-label="Lá vem cegonha, início"><span class="brand-mark" role="img" aria-label="Cegonha"><img src="/assets/logo-cegonha.webp" alt=""></span><span><strong class="brand-name">Lá vem cegonha</strong><small>chá de bebê</small></span></a><div class="top-actions"><button class="icon-button" data-admin-login>Administrador</button><button class="icon-button" data-settings>Detalhes do chá</button><button class="button button-primary" data-page="guests">＋ Convidados</button></div></header><nav class="nav-tabs" aria-label="Menu">${[['home','Visão geral'],['checklist','Checklist'],['guests','Convidados'],['messages','Recados'],['gifts','Presentes recebidos'],['invite','Convite']].map(([k,v])=>`<button class="nav-tab ${page===k?'active':''}" data-page="${k}">${v}</button>`).join('')}</nav>${previewMode?'<div class="preview-banner">Prévia visual: os dados ficam salvos neste navegador e ainda não são compartilhados entre convidados.</div>':''}${content}<footer><span>Lá vem cegonha · feito com carinho para a chegada de Anya</span><span>${previewMode?'Prévia local do Vercel':'Dados salvos neste servidor'}</span></footer></div>`;bindShell()}
function bindShell(){app.querySelectorAll('[data-page]').forEach(b=>b.addEventListener('click',e=>{e.preventDefault();page=b.dataset.page;render()}));app.querySelectorAll('[data-settings]').forEach(b=>b.addEventListener('click',openSettings));app.querySelectorAll('[data-shortcut]').forEach(b=>b.addEventListener('click',()=>useShortcut(b.dataset.shortcut)));app.querySelectorAll('[data-admin-login]').forEach(b=>b.addEventListener('click',async()=>{try{await authenticateAdmin();adminMode=true;await refresh()}catch(e){toast(e.message)}}))}
function eventCard(){return `<article class="hero"><div class="hero-copy"><span class="eyebrow">UM NOVO CAPÍTULO COMEÇA</span><h1><span class="hero-line">Nossa pequena</span><em class="hero-baby">Anya</em><span class="hero-line">está chegando</span></h1><p>Um cantinho para organizar cada detalhe e celebrar a chegada com as pessoas que amamos.</p><div class="hero-actions"><button class="button button-primary" data-page="invite">Ver convite <span>↗</span></button><button class="button button-light" data-settings>Editar detalhes</button></div></div><div class="hero-art">${inviteArt()}</div><span class="hero-note">♡ feito para nossa família</span></article>`}
function stats(){
 const yes=data.guests.filter(g=>g.status==='yes').length,pending=data.guests.filter(g=>g.status==='pending').length;
 const have=data.checklist.filter(x=>x.status==='have').length,expected=data.checklist.filter(x=>['expected','reserved','purchased'].includes(x.status)).length,total=data.checklist.length;
 const remaining=total-have-expected,pct=total?Math.round(have/total*100):0;
 return `<div class="dashboard-grid"><section class="panel"><div class="panel-heading"><div><span class="eyebrow">SEU PLANEJAMENTO</span><h2>Pequenos passos, grande amor</h2><p>O chá está tomando forma. Continue de onde parou.</p></div><span>♡</span></div><div class="metrics"><div class="stat-card"><strong>${data.guests.length}</strong><small>convidados</small></div><div class="stat-card"><strong>${yes}</strong><small>presenças confirmadas</small></div><div class="stat-card"><strong>${pending}</strong><small>aguardando resposta</small></div></div><div class="progress-heading"><strong>Enxoval</strong><span class="progress-percent">${pct}% concluído</span></div><div class="progress-track" role="progressbar" aria-label="Enxoval concluído" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${pct}"><div class="progress-fill" style="width:${pct}%"></div></div><div class="progress-caption"><span>Concluído: ${have}/${total} | Faltam: ${remaining} itens${expected?` | Vamos ganhar: ${expected}`:''}</span></div><div class="quick-links"><a href="#" class="quick-link" data-page="guests"><span>✉ Organizar convidados e convites</span><span>→</span></a><a href="#" class="quick-link" data-page="checklist"><span>☑ Continuar o checklist do enxoval</span><span>→</span></a></div></section><section class="panel"><div class="panel-heading"><div><span class="eyebrow">O GRANDE DIA</span><h2>Detalhes do chá</h2><p>Confira os dados do convite.</p></div></div><div class="stat-card"><strong style="font-size:18px">${esc(dateText(data.event.date,data.event.time))}</strong><small>${esc(data.event.address||'Endereço a definir')}</small></div><button class="button button-primary" data-settings style="margin-top:13px">${data.event.date?'Atualizar dados':'Definir data e local'}</button></section></div>`;
}
function nextActions(){
 const waiting=data.guests.filter(g=>g.status==='pending').length;
 const remaining=data.checklist.filter(x=>!['have','expected','reserved','purchased'].includes(x.status)).length;
 return `<section class="next-actions" aria-label="Próximas ações"><div class="next-actions-heading"><span class="eyebrow">PASSOS SIMPLES</span><h2>O que fazer agora</h2></div><div class="next-actions-grid"><button data-page="guests"><span class="next-icon">✉</span><strong>Organize os convidados</strong><small>${waiting} aguardando confirmação. Envie os links individuais.</small><span class="next-arrow">Abrir convidados →</span></button><button data-page="checklist"><span class="next-icon">♡</span><strong>Complete o enxoval</strong><small>${remaining} itens ainda faltam. Marque o que já têm ou vão ganhar.</small><span class="next-arrow">Abrir checklist →</span></button><button data-shortcut="photosUrl"><span class="next-icon">▧</span><strong>Compartilhe as fotos</strong><small>${data.event.photosUrl?'Álbum configurado. Abra ou compartilhe o link.':'Adicione o link do álbum quando estiver pronto.'}</small><span class="next-arrow">${data.event.photosUrl?'Abrir álbum':'Configurar fotos'} →</span></button></div></section>`;
}
function shortcutIcon(kind){const paths={gift:'<path d="M4 11h16v10H4zM2 7h20v4H2zM12 7v14M12 7c-3-1-5-2-5-4 0-3 5-3 5 4zm0 0c3-1 5-2 5-4 0-3-5-3-5 4z"/>',photos:'<path d="M4 7h4l2-2h4l2 2h4v13H4z"/><circle cx="12" cy="13" r="3"/>',map:'<path d="M12 22s7-7.1 7-13a7 7 0 0 0-14 0c0 5.9 7 13 7 13z"/><circle cx="12" cy="9" r="2"/>',music:'<path d="M9 18V5l11-2v13M9 7l11-2"/><ellipse cx="6" cy="18" rx="3" ry="2"/><ellipse cx="17" cy="16" rx="3" ry="2"/>',link:'<circle cx="18" cy="5" r="2"/><circle cx="5" cy="12" r="2"/><circle cx="18" cy="19" r="2"/><path d="m7 11 9-5M7 13l9 5"/>'};return `<svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">${paths[kind]}</svg>`}
function personalizeCard(){const rows=[['gift','Lista de presentes','giftUrl','Adicionar o link para presentear'],['photos','Fotos','photosUrl','Compartilhar um álbum'],['map','Local do evento','mapUrl','Endereço e rota para o chá'],['music','Música','musicUrl','Compartilhar a playlist'],['link','Link da página','guests','Convite individual de cada pessoa']];return `<section class="personalize-card" aria-label="Personalize seu chá"><div class="personalize-heading"><span class="eyebrow">DO SEU JEITO</span><h2>Personalize seu chá <span>com carinho.</span></h2><p>Prepare os detalhes e facilite a vida dos convidados.</p></div><div class="personalize-rows">${rows.map(([icon,label,key,tip])=>`<button class="personalize-row" data-shortcut="${key}"><span class="personalize-icon">${shortcutIcon(icon)}</span><span class="personalize-label"><strong>${label}</strong><small>${key==='guests'?tip:data.event[key]?'Link pronto · tocar para abrir':tip}</small></span><span class="personalize-arrow" aria-hidden="true">›</span></button>`).join('')}</div></section>`}
function useShortcut(key){if(key==='guests'){page='guests';guests();document.querySelector('#guest-list')?.scrollIntoView({behavior:'smooth'});return}if(key==='mapUrl'&&!data.event[key]){openSettings('address');return}if(data.event[key]){window.open(data.event[key],'_blank','noopener,noreferrer');return}openSettings(key)}
function home(){shell(`${eventCard()}${stats()}${nextActions()}${personalizeCard()}`)}
async function loadPublicEvent(){try{const {event}=await api('/public-event',{headers:{Authorization:''}});const wrap=$('.public-wrap');if(!wrap)return;wrap.insertAdjacentHTML('beforeend',`${routePanel(event)}${contributionPanel(event)}${event.dressCode?`<section class="rsvp-panel"><h2>Dress code</h2><p>${esc(event.dressCode)}</p></section>`:''}${weatherPanel(event)}`);loadWeather(event);bindPix()}catch{}}
function rsvpDetails(guest={}){return `<div class="rsvp-extra"><label>Vai levar acompanhante? Quantas pessoas vão ao todo?<select name="partySize">${Array.from({length:8},(_,i)=>`<option value="${i+1}" ${Number(guest.partySize||1)===i+1?'selected':''}>${i+1} pessoa${i?'s':''}</option>`).join('')}</select></label><label>Vai trazer criança?<select name="bringingChild"><option value="" ${guest.bringingChild==null?'selected':''}>Prefiro não informar</option><option value="yes" ${guest.bringingChild===true?'selected':''}>Sim</option><option value="no" ${guest.bringingChild===false?'selected':''}>Não</option></select></label><label>Alguma restrição alimentar?<input name="dietaryRestriction" maxlength="180" placeholder="Opcional" value="${esc(guest.dietaryRestriction||'')}"></label></div>`}
function rsvpExtra(root){return {partySize:Number(root.querySelector('[name="partySize"]').value),bringingChild:root.querySelector('[name="bringingChild"]').value==='yes'?true:root.querySelector('[name="bringingChild"]').value==='no'?false:null,dietaryRestriction:root.querySelector('[name="dietaryRestriction"]').value}}
function publicHome(){
 document.body.classList.remove('boy');document.title='Lá vem cegonha · Anya';
 app.innerHTML=`<main class="public-page"><div class="public-wrap"><div class="public-admin-bar"><button class="button button-light" data-admin-login>Administrador</button></div><div class="brand public-brand"><span class="brand-mark" role="img" aria-label="Cegonha"><img src="/assets/logo-cegonha.webp" alt=""></span><span><strong class="brand-name">Lá vem cegonha</strong><small>chá de bebê</small></span></div><div class="public-poster"><img class="invite-poster" src="/assets/convite-anya-final.jpg" onerror="this.onerror=null;this.src='/assets/convite-anya.webp'" alt="Convite final do chá de bebê da Anya"><button type="button" class="poster-rsvp-jump" id="poster-rsvp-jump">♡ Confirmar presença aqui ↓</button></div><section class="rsvp-panel public-access" id="confirmar"><button class="guest-pill guest-pill-filled public-rsvp-cta" id="open-public-rsvp" aria-expanded="false" aria-controls="public-rsvp-form">♡ Confirmar presença</button><h2>Confirme sua presença</h2><p>Leva menos de um minuto. Se você recebeu um link individual, pode confirmar diretamente nele.</p><form id="public-rsvp-form" class="public-rsvp-form" hidden><label for="public-guest-name">Seu nome</label><input id="public-guest-name" name="name" type="text" maxlength="90" autocomplete="name" required placeholder="Como podemos chamar você?">${rsvpDetails()}<div class="guest-answer-buttons"><button type="submit" name="status" value="yes" class="guest-answer-yes">Sim, vou!</button><button type="submit" name="status" value="no" class="guest-answer-no">Não poderei ir</button></div><p id="public-rsvp-error" class="rsvp-error" role="alert"></p></form></section></div></main>`;
 bindShell();
 const giftsButton=document.createElement('button');giftsButton.className='button button-light public-gifts-button';giftsButton.textContent='Ver lista do enxoval ↗';giftsButton.onclick=showGiftCatalog;$('#confirmar').append(giftsButton);$('.public-wrap').insertAdjacentHTML('beforeend',messagePanel());bindMessagePanel();loadMural();loadPublicEvent();$('#poster-rsvp-jump').onclick=()=>{$('#open-public-rsvp').click();$('#confirmar').scrollIntoView({behavior:'smooth',block:'start'})};
 $('#open-public-rsvp').onclick=()=>{const form=$('#public-rsvp-form');form.hidden=false;$('#open-public-rsvp').setAttribute('aria-expanded','true');$('#public-guest-name').focus()};
 $('#public-rsvp-form').onsubmit=async e=>{e.preventDefault();const form=e.currentTarget,button=e.submitter,status=button?.value;if(!status)return;const buttons=form.querySelectorAll('button');buttons.forEach(b=>b.disabled=true);$('#public-rsvp-error').textContent='';try{const {guest}=await api('/public-rsvp',{method:'POST',body:JSON.stringify({name:form.elements.name.value,status,...rsvpExtra(form)})});history.replaceState(null,'',publicInviteUrl(guest.token));await publicInvite()}catch(err){$('#public-rsvp-error').textContent=err.message;buttons.forEach(b=>b.disabled=false)}}
}
function categoryMarkup(groups){return groups.map(g=>`<article class="category-card"><button class="category-header" aria-expanded="true"><span class="category-icon">${esc(g.icon||'♡')}</span><span class="category-head-copy"><strong>${esc(g.category)}</strong><small>${['','Essencial','Importante','Opcional'][g.priority]}</small></span><span class="category-count">${g.items.length} itens</span><span>⌄</span></button><div>${g.items.map(x=>`<div class="check-item"><div><div class="check-name">${esc(x.name)}${x.status==='reserved'?' · Reservado':x.status==='purchased'?' · Já comprado':''}${x.reserved_by?` por ${esc(data.guests.find(g=>g.id===x.reserved_by)?.name||'convidado')}`:''}</div><div class="check-meta">${esc(x.quantity||'')}</div><button class="shop-link" type="button" data-shop="${esc(x.id)}">Lojas e faixa de preço ↗</button></div><div class="check-actions">${checklistView==='have'?`<button class="check-action" data-check="${x.id}" data-status="expected">Vamos ganhar</button><button class="check-action" data-check="${x.id}" data-status="">Voltar para Faltam</button>`:checklistView==='expected'?`<button class="check-action" data-check="${x.id}" data-status="purchased">Já comprado</button><button class="check-action" data-check="${x.id}" data-status="have">Já temos</button><button class="check-action" data-check="${x.id}" data-status="">Voltar para Faltam</button>`:`<button class="check-action" data-check="${x.id}" data-status="have">Tenho</button><button class="check-action" data-check="${x.id}" data-status="expected">Vamos ganhar</button><button class="check-action ${x.status==='missing'?'active':''}" data-check="${x.id}" data-status="missing">Comprar</button>`}</div></div>`).join('')}</div></article>`).join('')}
let checklistView='missing';
function checklist(){
 const haveItems=data.checklist.filter(x=>x.status==='have');
 const expectedItems=data.checklist.filter(x=>['expected','reserved','purchased'].includes(x.status));
 const missingItems=data.checklist.filter(x=>!['have','expected','reserved','purchased'].includes(x.status));
 const source=checklistView==='have'?haveItems:checklistView==='expected'?expectedItems:missingItems;
 const pct=data.checklist.length?Math.round(haveItems.length/data.checklist.length*100):0;
 const shown=source.filter(x=>(priority==='all'||String(x.priority)===priority)&&(!checkQuery||`${x.name} ${x.category}`.toLocaleLowerCase('pt-BR').includes(checkQuery)));
 const grouped=[];
 for(const x of shown){let g=grouped.find(y=>y.category===x.category&&y.priority===x.priority);if(!g){g={category:x.category,priority:x.priority,icon:x.icon,items:[]};grouped.push(g)}g.items.push(x)}
 shell(`<section class="content-panel"><div class="panel-heading"><div><span class="eyebrow">SEU GUIA PRÁTICO</span><h1 class="content-title">♡ Checklist do enxoval</h1><p>Marquem o que já têm ou sabem que vão ganhar. Ambos saem da lista dos convidados.</p></div><div class="toolbar"><input id="check-search" class="search-input" placeholder="Buscar item" value="${esc(checkQuery)}"><span class="progress-percent">${pct}% concluído</span></div></div><div class="progress-track checklist-progress" role="progressbar" aria-label="Enxoval concluído" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${pct}"><div class="progress-fill" style="width:${pct}%"></div></div><p class="checklist-summary">Concluído: <strong>${haveItems.length}/${data.checklist.length}</strong> <span aria-hidden="true">|</span> Faltam: <strong>${missingItems.length} itens</strong>${expectedItems.length?` <span aria-hidden="true">|</span> Vamos ganhar: <strong>${expectedItems.length}</strong>`:''}</p><div class="filter-row" aria-label="Listas do enxoval"><button class="filter-pill ${checklistView==='missing'?'active':''}" data-list="missing">Faltam (${missingItems.length})</button><button class="filter-pill ${checklistView==='expected'?'active':''}" data-list="expected">Vamos ganhar (${expectedItems.length})</button><button class="filter-pill ${checklistView==='have'?'active':''}" data-list="have">Temos (${haveItems.length})</button></div><div class="filter-row">${['all','1','2','3'].map(p=>`<button class="filter-pill ${p===priority?'active':''}" data-priority="${p}">${p==='all'?'Todas':({1:'Essencial',2:'Importante',3:'Opcional'}[p])}</button>`).join('')}</div><div class="category-grid">${categoryMarkup(grouped)}</div>${shown.length?'':`<div class="empty-state">${checklistView==='have'?'Ainda não há itens na lista Temos.':checklistView==='expected'?'Ainda não há itens em Vamos ganhar.':'Nenhum item pendente nesta seleção.'}</div>`}<p class="subtext" style="margin-top:18px">Dica de segurança: use uma superfície firme e plana para o sono; evite itens soltos no berço.</p></section>`);
 $('#check-search').addEventListener('input',e=>{checkQuery=e.target.value.toLocaleLowerCase('pt-BR');checklist()});
 app.querySelectorAll('[data-list]').forEach(b=>b.addEventListener('click',()=>{checklistView=b.dataset.list;checklist()}));
 app.querySelectorAll('[data-priority]').forEach(b=>b.addEventListener('click',()=>{priority=b.dataset.priority;checklist()}));
 app.querySelectorAll('[data-shop]').forEach(b=>b.onclick=async()=>{const item=data.checklist.find(x=>x.id===b.dataset.shop);const old=Array.isArray(item.shop_links)?item.shop_links:[];const raw=prompt('Lojas (uma por linha: Nome | https://link). Até 5. Deixe vazio para usar a busca padrão.',old.map(x=>`${x.label} | ${x.url}`).join('\n'));if(raw===null)return;let links;try{links=raw.trim()?raw.trim().split(/\n/).map(line=>{const i=line.indexOf('|');if(i<1)throw Error('Use Nome | URL em cada linha.');return {label:line.slice(0,i).trim(),url:line.slice(i+1).trim()}}):[];if(links.length>5)throw Error('Máximo de cinco lojas.')}catch(e){toast(e.message);return}const band=prompt('Faixa estimada: ate50, 50a100, 100a200, acima200. Deixe vazio se desconhecida.',item.price_band||'');if(band===null)return;try{await api('/checklist/'+item.id+'/shops',{method:'PUT',body:JSON.stringify({links,priceBand:band.trim()})});await refresh(false);checklist()}catch(e){toast(e.message)}});
 app.querySelectorAll('[data-check]').forEach(b=>b.addEventListener('click',async()=>{const item=data.checklist.find(x=>x.id===b.dataset.check);const status=b.dataset.status==='missing'&&item.status==='missing'?'':b.dataset.status;try{await api('/checklist/'+item.id,{method:'PATCH',body:JSON.stringify({status})});await refresh(false);checklist()}catch(e){toast(e.message)}}));
 app.querySelectorAll('.category-header').forEach(b=>b.addEventListener('click',()=>{const div=b.nextElementSibling;div.classList.toggle('hidden');b.setAttribute('aria-expanded',String(!div.classList.contains('hidden')))}));
}
function messagesAdmin(){
 const pending=(data.messages||[]).filter(m=>!m.approved),published=(data.messages||[]).filter(m=>m.approved);
 const cards=messages=>messages.map(m=>`<article class="message-admin-card"><div><strong>${esc(m.author_name)}</strong><small>${new Date(m.created_at).toLocaleString('pt-BR')}</small><p>${esc(m.message)}</p></div><div class="message-admin-actions"><button class="button button-primary button-small" data-message-toggle="${esc(m.id)}" data-approved="${m.approved?'false':'true'}">${m.approved?'Ocultar':'Publicar'}</button><button class="button button-danger button-small" data-message-delete="${esc(m.id)}">Excluir</button></div></article>`).join('');
 shell(`<section class="content-panel"><div class="panel-heading"><div><span class="eyebrow">CARINHO DOS CONVIDADOS</span><h1 class="content-title">Recados para a Anya</h1><p>Leia e aprove os desejos e dicas antes de aparecerem na página dos convidados.</p></div></div><h2>Pendentes (${pending.length})</h2>${cards(pending)||'<p class="empty-state">Nenhum recado aguardando aprovação.</p>'}<h2>Publicados (${published.length})</h2>${cards(published)||'<p class="subtext">Ainda não há recados publicados.</p>'}</section>`);
 app.querySelectorAll('[data-message-toggle]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{await api('/messages/'+b.dataset.messageToggle,{method:'PATCH',body:JSON.stringify({approved:b.dataset.approved==='true'})});await refresh(false);messagesAdmin()}catch(err){toast(err.message);b.disabled=false}});
 app.querySelectorAll('[data-message-delete]').forEach(b=>b.onclick=async()=>{if(!confirm('Excluir este recado?'))return;b.disabled=true;try{await api('/messages/'+b.dataset.messageDelete,{method:'DELETE'});await refresh(false);messagesAdmin()}catch(err){toast(err.message);b.disabled=false}});
}
function gifts(){
 const open=!!data.giftsOpen;
 const options=data.guests.map(g=>`<option value="${esc(g.id)}">${esc(g.name)}</option>`).join('');
 const items=data.checklist.map(item=>`<option value="${esc(item.id)}">${esc(item.name)} · ${esc(item.category)}</option>`).join('');
 const records=(data.gifts||[]).map(g=>{
  const guest=data.guests.find(x=>x.id===g.guest_id),item=data.checklist.find(x=>x.id===g.item_id);
  return `<article class="gift-record"><div><strong>${esc(g.donor_name)}</strong><span class="subtext">${esc(g.gift_description)}${item?' · Enxoval':''} · ${new Date(g.created_at).toLocaleDateString('pt-BR')}</span>${g.message?`<p>“${esc(g.message)}” ${g.publish_message?'· No mural':'· Privado'}</p>`:''}</div><div class="gift-record-actions"><button class="button button-light button-small" data-gift-edit="${esc(g.id)}">Mensagem / mural</button><button class="button button-primary button-small" data-gift-thanks="${esc(g.id)}">Agradecer</button><button class="button button-light button-small" data-gift-photo="${esc(g.id)}">Enviar foto</button><button class="button button-danger button-small" data-gift-delete="${esc(g.id)}">Excluir</button></div></article>`;
 }).join('');
 shell(`<section class="content-panel"><div class="panel-heading"><div><span class="eyebrow">DEPOIS DO CHÁ</span><h1 class="content-title">Presentes recebidos</h1><p>Registrem os presentes pessoalmente depois do dia 29 de novembro. Sem pagamentos ou cobranças.</p></div></div>${open?`<form id="gift-form" class="gift-form"><label>Convidado da lista <select name="guestId"><option value="">Outro / não cadastrado</option>${options}</select></label><label>Quem presenteou <input name="donorName" required minlength="2" maxlength="90" placeholder="Nome da pessoa"></label><label>Item do enxoval <select name="itemId"><option value="">Outro presente</option>${items}</select></label><label>Presente recebido <input name="description" required minlength="2" maxlength="180" placeholder="Ex.: carrinho, roupas, fraldas"></label><label class="gift-full">Recado da pessoa para a Anya <textarea name="message" maxlength="300" rows="3" placeholder="Opcional"></textarea></label><label class="gift-full gift-consent"><input name="publishMessage" type="checkbox"> A pessoa autorizou publicar nome e recado no mural</label><button class="button button-primary" type="submit">Registrar presente recebido</button></form>`:'<div class="empty-state">O registro manual será liberado em 30 de novembro, no horário do Rio de Janeiro. Até lá, use o checklist para marcar o que vocês já têm.</div>'}<div class="gift-records"><h2>Registrados (${(data.gifts||[]).length})</h2>${records||'<p class="subtext">Nenhum presente registrado ainda.</p>'}</div><p class="subtext">Um item associado ao enxoval passa para “Temos”. Excluir o registro não devolve o item automaticamente; isso pode ser feito no checklist. O mural só exibe recados autorizados.</p></section>`);
 const form=$('#gift-form');
 if(form){form.elements.guestId.onchange=()=>{const g=data.guests.find(x=>x.id===form.elements.guestId.value);if(g)form.elements.donorName.value=g.name};form.elements.itemId.onchange=()=>{const x=data.checklist.find(x=>x.id===form.elements.itemId.value);if(x)form.elements.description.value=x.name};form.onsubmit=async e=>{e.preventDefault();const body=Object.fromEntries(new FormData(form));body.publishMessage=!!form.elements.publishMessage.checked;const submit=form.querySelector('[type="submit"]');submit.disabled=true;try{await api('/gifts',{method:'POST',body:JSON.stringify(body)});toast('Presente registrado');await refresh(false);gifts()}catch(err){toast(err.message);submit.disabled=false}}}
 app.querySelectorAll('[data-gift-edit]').forEach(b=>b.onclick=async()=>{const g=data.gifts.find(x=>x.id===b.dataset.giftEdit);const message=prompt('Recado da pessoa para a Anya:',g.message||'');if(message===null)return;const publishMessage=!!message&&confirm('A pessoa autorizou publicar o nome e o recado no mural? Clique OK somente se houver autorização.');try{await api('/gifts/'+g.id,{method:'PATCH',body:JSON.stringify({message,publishMessage})});await refresh(false);gifts()}catch(err){toast(err.message)}});
 app.querySelectorAll('[data-gift-delete]').forEach(b=>b.onclick=async()=>{if(!confirm('Excluir este registro de presente?'))return;try{await api('/gifts/'+b.dataset.giftDelete,{method:'DELETE'});await refresh(false);gifts()}catch(err){toast(err.message)}});
 app.querySelectorAll('[data-gift-thanks]').forEach(b=>b.onclick=()=>sendGiftMessage(b.dataset.giftThanks,false));
 app.querySelectorAll('[data-gift-photo]').forEach(b=>b.onclick=()=>sendGiftMessage(b.dataset.giftPhoto,true));
}
async function sendGiftMessage(id,photo){
 const gift=data.gifts.find(x=>x.id===id),guest=data.guests.find(x=>x.id===gift.guest_id);
 let message=`${gift.donor_name}, obrigado pelo carinho com a Anya e pelo presente ${gift.gift_description}! Sua presença fez esse momento ainda mais especial. 💜`;
 if(photo){const url=prompt('Cole o link da foto ou lembrança digital que vocês querem enviar:',data.event.photosUrl||'');if(!url)return;try{if(!['https:','http:'].includes(new URL(url).protocol))throw Error()}catch{toast('Informe um link válido');return}message+=`\n\nUma lembrança para você: ${url}`}
 const edited=prompt('Revise a mensagem antes de enviar:',message);if(!edited)return;
 const phone=(guest?.phone||'').replace(/\D/g,'');
 if(phone)window.open(`https://wa.me/${phone}?text=${encodeURIComponent(edited)}`,'_blank','noopener');
 else try{await navigator.clipboard.writeText(edited);toast('Mensagem copiada para enviar à pessoa')}catch{prompt('Copie a mensagem:',edited)}
}
function guestRows(){const q=guestQuery.toLocaleLowerCase('pt-BR');return data.guests.filter(g=>(!q||`${g.name} ${g.phone||''}`.toLocaleLowerCase('pt-BR').includes(q))&&(guestFilter==='all'||g.status===guestFilter)).map(g=>`<tr><td><span class="guest-name">#${String(data.guests.indexOf(g)+1).padStart(3,'0')} · ${esc(g.name)}</span><span class="subtext">${esc(g.phone||g.note||'')}</span></td><td><span class="badge badge-${g.status==='yes'?'yes':g.status==='no'?'no':'pending'}">${g.status==='yes'?'Confirmado':g.status==='no'?'Não vai':'Aguardando'}</span>${g.respondedAt?`<span class="subtext">${new Date(g.respondedAt).toLocaleString('pt-BR',{dateStyle:'short',timeStyle:'short'})}</span>`:''}</td><td>${g.partySize||1} pessoa${(g.partySize||1)>1?'s':''}${g.bringingChild===true?'<br>Criança: sim':''}${g.dietaryRestriction?`<br>Alimentação: ${esc(g.dietaryRestriction)}`:''}</td><td><div class="guest-actions"><button class="button button-light button-small" data-copy="${g.id}">Copiar link</button><button class="button button-primary button-small" data-send="${g.id}">WhatsApp</button><button class="button button-light button-small" data-edit="${g.id}" aria-label="Editar">✎</button></div></td></tr>`).join('')}
function guests(){const yes=data.guests.filter(g=>g.status==='yes').length,no=data.guests.filter(g=>g.status==='no').length,pending=data.guests.length-yes-no;shell(`${personalizeCard()}<section id="guest-list" class="content-panel"><div class="panel-heading"><div><span class="eyebrow">QUEM VAI CELEBRAR COM VOCÊS</span><h1 class="content-title">Lista de convidados</h1><p>Crie um convite individual e acompanhe cada confirmação.</p></div><div class="toolbar"><button class="button button-light" id="export-csv">Exportar CSV</button><button class="button button-primary" id="add-guest">＋ Adicionar</button></div></div><div class="metrics"><div class="stat-card"><strong>${data.guests.length}</strong><small>Total</small></div><div class="stat-card"><strong>${yes}</strong><small>Confirmados</small></div><div class="stat-card"><strong>${pending}</strong><small>Aguardando · ${no} não vão</small></div></div><div class="filter-row"><input id="guest-search" class="search-input" placeholder="Buscar nome ou telefone" value="${esc(guestQuery)}"><select id="guest-filter" class="select-input"><option value="all">Todos os status</option><option value="pending" ${guestFilter==='pending'?'selected':''}>Aguardando</option><option value="yes" ${guestFilter==='yes'?'selected':''}>Confirmado</option><option value="no" ${guestFilter==='no'?'selected':''}>Não vai</option></select></div><div class="guest-table-wrap"><table class="guest-table"><thead><tr><th>Convidado</th><th>Resposta</th><th>Pessoas / detalhes</th><th>Enviar convite</th></tr></thead><tbody>${guestRows()}</tbody></table></div><div class="rsvp-panel"><h2>Palpites da Anya</h2>${(data.guesses||[]).map(x=>{const g=data.guests.find(y=>y.id===x.guest_id);return `<p>${esc(g?.name||'Convidado')} · ${esc(x.birth_date||'sem data')} · ${esc(x.weight_grams)} g</p>`}).join('')||'<p>Ainda sem palpites.</p>'}</div>${data.guests.length?'':'<div class="empty-state">Sua lista começa com um nome querido. Adicione convidados para gerar links individuais de convite.</div>'}</section>`);$('#add-guest').onclick=()=>openGuest();$('#guest-search').addEventListener('input',e=>{guestQuery=e.target.value;guests()});$('#guest-filter').addEventListener('change',e=>{guestFilter=e.target.value;guests()});$('#export-csv').onclick=exportCsv;app.querySelectorAll('[data-copy]').forEach(b=>b.onclick=()=>copyInvite(b.dataset.copy));app.querySelectorAll('[data-send]').forEach(b=>b.onclick=()=>sendInvite(b.dataset.send));app.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>openGuest(data.guests.find(g=>g.id===b.dataset.edit)))}
function invite(){const link=INVITE_BASE;shell(`<section class="content-panel"><div class="panel-heading"><div><span class="eyebrow">UM CONVITE FEITO COM CARINHO</span><h1 class="content-title">Convite do chá</h1><p>Personalize os dados e envie um link único para cada convidado.</p></div><button class="button button-primary" data-settings>Editar convite</button></div><div class="invite-preview"><div class="invite-poster-wrap">${invitePoster(data.event)}</div><aside class="invite-side"><img class="brand-full" src="/assets/logo-cegonha.webp" alt="Lá vem cegonha — chá de bebê"><span class="eyebrow">COMPARTILHAMENTO</span><h3>Um link para cada pessoa</h3><p>Na lista de convidados, use “Copiar link” ou “WhatsApp”. Cada pessoa recebe uma página própria para confirmar presença, com a resposta ligada ao nome dela.</p><div class="link-box">${esc(link)}[código do convidado]</div><button class="button button-primary" data-page="guests" style="width:100%">Abrir convidados →</button><p style="margin:12px 0 0">Links ativos: <strong>${data.guests.length}</strong> · respostas recebidas: <strong>${data.guests.filter(g=>g.status!=='pending').length}</strong></p></aside></div></section>`)}
function render(){if(location.pathname.startsWith('/convite/'))return publicInvite();if(!adminMode)return publicHome();if(page==='home')home();if(page==='checklist')checklist();if(page==='guests')guests();if(page==='messages')messagesAdmin();if(page==='gifts')gifts();if(page==='invite')invite()}
function statusName(s){return s==='yes'?'Presença confirmada':s==='no'?'Não poderá comparecer':'Resposta registrada'}
async function publicInvite(){
 const token=decodeURIComponent(location.pathname.split('/')[2]||'');
 try{
  const {guest:g,event,reserved=[],guess}=await api('/invite/'+encodeURIComponent(token));
  const baby='Anya',answered=g.status==='yes'||g.status==='no';
  document.body.classList.remove('boy');
  document.title='Convite para Anya · Lá vem cegonha';
  document.querySelector('meta[name="theme-color"]')?.setAttribute('content','#f5eafa');
  const external=(url,label)=>url?`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${label} ↗</a>`:'';
  app.innerHTML=`<main class="public-page"><div class="public-wrap"><div class="brand public-brand"><span class="brand-mark" role="img" aria-label="Cegonha"><img src="/assets/logo-cegonha.webp" alt=""></span><span><strong class="brand-name">Lá vem cegonha</strong><small>chá de bebê</small></span></div>${previewMode?'<div class="preview-banner">Prévia visual: os dados ficam neste navegador.</div>':''}
   <article class="guest-event-card"><span class="eyebrow">UM CONVITE SÓ PARA VOCÊ</span><h1>Chá de bebê de ${baby}</h1><p class="guest-greeting">${esc(g.name)}, vamos celebrar a chegada de ${baby}!</p><div class="guest-event-line"><span aria-hidden="true">▣</span><div><strong>Evento</strong><p>${esc(dateText(event.date,event.time))}</p><p>${esc(event.address||'Local a definir')}</p>${external(event.mapUrl,'Como chegar')}</div></div>
   <div class="guest-event-buttons"><button id="open-rsvp" class="guest-pill guest-pill-outline">${answered?'Ver ou alterar presença':'Confirmar presença'}</button><button id="open-gifts" class="guest-pill guest-pill-filled">Ver lista do enxoval</button></div>
   <section class="guest-rsvp" id="rsvp-box" ${answered?'':'hidden'} aria-live="polite"><h2>${answered?esc(statusName(g.status)):`Você vem, ${esc(g.name)}?`}</h2><p>${answered?'Sua resposta já foi registrada. Você pode alterá-la aqui.':'Basta tocar na sua resposta. Uma pessoa já está selecionada.'}</p>${rsvpDetails(g)}<div class="guest-answer-buttons"><button data-answer="yes" class="guest-answer-yes">${answered?'Atualizar: vou sim':'Sim, vou!'}</button><button data-answer="no" class="guest-answer-no">Não poderei ir</button></div><p id="rsvp-error" role="status" class="rsvp-error"></p></section></article>
   <div class="public-poster">${invitePoster(event)}<button type="button" class="poster-rsvp-jump" id="poster-rsvp-jump">♡ Confirmar presença aqui ↑</button></div><article class="invite-card"><div class="overline">NOSSA PEQUENA</div><h1>${baby}</h1><h2>ESTÁ CHEGANDO</h2><p class="message">♡ ${esc(event.message||'Venha celebrar conosco!')} ♡</p><div class="event-detail"><div><strong>◷ DATA E HORÁRIO</strong><span>${esc(dateText(event.date,event.time))}</span></div><div><strong>⌖ LOCAL</strong><span>${esc(event.address||'Local a definir')}</span></div></div><p class="invite-footer">Um convite especial para ${esc(g.name)}</p>${event.photosUrl||event.musicUrl?`<div class="guest-extra-links">${external(event.photosUrl,'Fotos')}${external(event.musicUrl,'Música')}</div>`:''}</article>${routePanel(event)}${contributionPanel(event)}${event.dressCode?`<section class="rsvp-panel"><h2>Dress code</h2><p>${esc(event.dressCode)}</p></section>`:''}${weatherPanel(event)}${reserved.length?`<section class="rsvp-panel"><h2>Seus itens separados</h2>${reserved.map(x=>`<p>${esc(x.name)} · ${x.status==='purchased'?'Comprado':'Reservado'} ${x.status==='reserved'?`<button class="button button-primary button-small" data-purchased="${esc(x.id)}">Já comprei</button>`:''}</p>`).join('')}</section>`:''}${guessPanel(token,guess)}</div></main>`;
  loadWeather(event);bindPix();bindGuess(token);app.querySelectorAll('[data-purchased]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{await api('/purchase/'+b.dataset.purchased,{method:'POST',body:JSON.stringify({token})});await publicInvite()}catch(e){toast(e.message);b.disabled=false}});
  $('#open-rsvp').onclick=()=>{const panel=$('#rsvp-box');panel.hidden=false;panel.scrollIntoView({behavior:'smooth',block:'nearest'})};
  $('#open-gifts')?.addEventListener('click',showGiftCatalog);$('.public-wrap').insertAdjacentHTML('beforeend',messagePanel(token,g.name));bindMessagePanel(token);loadMural();$('#poster-rsvp-jump').onclick=()=>{$('#open-rsvp').click();$('#rsvp-box').scrollIntoView({behavior:'smooth',block:'center'})};
  app.querySelectorAll('[data-answer]').forEach(button=>button.addEventListener('click',async()=>{
   const buttons=app.querySelectorAll('[data-answer]');buttons.forEach(b=>b.disabled=true);
   $('#rsvp-error').textContent='';
   try{await api('/rsvp/'+encodeURIComponent(token),{method:'POST',body:JSON.stringify({status:button.dataset.answer,...rsvpExtra($('#rsvp-box'))})});await publicInvite();$('#rsvp-box').hidden=false;$('#rsvp-box').scrollIntoView({behavior:'smooth',block:'nearest'})}
   catch(err){$('#rsvp-error').textContent=err.message;buttons.forEach(b=>b.disabled=false)}
  }));
 }catch(err){app.innerHTML=`<main class="public-page"><div class="rsvp-panel"><h2>Este convite não está disponível</h2><p>Confira o link recebido ou peça outro à família.</p></div></main>`}
}

function openGuest(g){const d=$('#guest-dialog'),f=$('#guest-form');f.reset();f.elements.id.value=g?.id||'';f.elements.name.value=g?.name||'';f.elements.phone.value=g?.phone||'';f.elements.note.value=g?.note||'';$('#guest-dialog-title').textContent=g?'Editar convidado':'Adicionar convidado';d.showModal()}
function openSettings(){const d=$('#settings-dialog'),f=$('#settings-form'),e=data.event;f.elements.baby.value='Anya';f.elements.date.value=e.date||'';f.elements.time.value=e.time||'';f.elements.address.value=e.address||'';f.elements.message.value=e.message||'';f.elements.mapUrl.value=e.mapUrl||'';f.elements.dressCode.value=e.dressCode||'';f.elements.pixKey.value=e.pixKey||'';f.elements.pixRecipient.value=e.pixRecipient||'';for(const field of ['giftUrl','photosUrl','musicUrl'])f.elements[field].value=e[field]||'';d.showModal();if(typeof arguments[0]==='string')f.elements[arguments[0]]?.focus()}
document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>b.closest('dialog').close());
$('#guest-form').addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.target),id=f.get('id'),body={name:f.get('name'),phone:f.get('phone'),note:f.get('note')};try{await api('/guests'+(id?'/'+id:''),{method:id?'PATCH':'POST',body:JSON.stringify(body)});$('#guest-dialog').close();toast(id?'Convidado atualizado':'Convidado adicionado');await refresh();page='guests';guests()}catch(err){toast(err.message)}});
$('#settings-form').addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.target),body=Object.fromEntries(f.entries());try{await api('/event',{method:'PUT',body:JSON.stringify(body)});$('#settings-dialog').close();toast('Detalhes atualizados');await refresh()}catch(err){toast(err.message)}});
async function copyInvite(id){const g=data.guests.find(x=>x.id===id),url=publicInviteUrl(g.token);try{await navigator.clipboard.writeText(url);toast('Link de convite copiado')}catch{prompt('Copie o link do convite:',url)}}
function sendInvite(id){const g=data.guests.find(x=>x.id===id),url=publicInviteUrl(g.token),text=`Oi, ${g.name}! 💛\n\n${data.event.message||'Venha celebrar conosco!'}\n\n${data.event.baby} está chegando!\n${dateText(data.event.date,data.event.time)}\n${data.event.address||'Local a definir'}\n\nConfirme por aqui: ${url}`;const phone=(g.phone||'').replace(/\D/g,'');window.open(`https://wa.me/${phone}?text=${encodeURIComponent(text)}`,'_blank','noopener')}
function exportCsv(){const rows=[['Nome','Telefone','Status','Pessoas','Observação','Link de convite'],...data.guests.map(g=>[g.name,g.phone||'',g.status==='yes'?'Confirmado':g.status==='no'?'Não vai':'Aguardando',g.partySize||1,g.note||'',publicInviteUrl(g.token)])];const csv='\uFEFF'+rows.map(r=>r.map(c=>'"'+String(c).replaceAll('"','""')+'"').join(';')).join('\n'),a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download='convidados-la-vem-cegonha.csv';a.click();URL.revokeObjectURL(a.href)}
async function refresh(draw=true){try{data=await api('/data');if(draw)render()}catch(e){app.innerHTML=`<main class="public-page"><section class="rsvp-panel"><h2>Não consegui conectar ao Lá vem cegonha</h2><p>${esc(e.message)}. Inicie o servidor usando <code>npm start</code>.</p></section></main>`}}
if(location.pathname.startsWith('/convite/'))publicInvite();else publicHome();
